const contactForm=document.querySelector('#contact-form');
if(contactForm){const status=document.querySelector('#contact-status');const button=contactForm.querySelector('button[type="submit"]');contactForm.addEventListener('submit',async event=>{event.preventDefault();if(!contactForm.reportValidity())return;const fields=new FormData(contactForm);const payload={name:fields.get('name'),email:fields.get('email'),phone:fields.get('phone'),enquiryType:fields.get('enquiry_type'),message:fields.get('message')};button.disabled=true;status.textContent='Sending your enquiry…';try{const response=await fetch('/api/contact-enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Could not send your enquiry.');contactForm.reset();status.textContent='Thank you — your enquiry has been sent to Cookies Cakes.';}catch(error){status.textContent=error.message||'Could not send your enquiry. Please try again.';}finally{button.disabled=false;}});}
